import React, { useState } from 'react';
import { Button } from '../ui/Button';
import {
  Home,
  Briefcase,
  FolderOpen,
  Hash,
  Award,
  HelpCircle,
  Star,
  Trophy,
  MessageSquare,
  DollarSign,
  Mail,
  Menu,
  X,
} from 'lucide-react';

export default function MergedNavbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const menuItems = [
    { icon: Home, label: 'HOME', href: '#home' },
    { icon: Briefcase, label: 'SERVICES', href: '#services' },
    { icon: FolderOpen, label: 'PORTFOLIO', href: '#portfolio' },
    { icon: Hash, label: 'NUMERIC', href: '#numeric' },
    { icon: Award, label: 'SKILLS', href: '#skills' },
    { icon: HelpCircle, label: 'FAQS', href: '#faqs' },
  ];

  const experienceItems = [
    { icon: Star, label: 'EXPERIENCE', href: '#experience' },
    { icon: Trophy, label: 'WHAT YOU GET', href: '#what-you-get' },
    { icon: Award, label: 'AWARDS', href: '#awards' },
    { icon: MessageSquare, label: 'TESTIMONIAL', href: '#testimonial' },
    { icon: DollarSign, label: 'PRICING', href: '#pricing' },
    { icon: Mail, label: 'CONTACT FORM', href: '#contact' },
  ];

  return (
    <>
      {/* Top Navigation Bar */}
      <nav className="fixed top-0 left-0 right-0 z-50 bg-black/80 backdrop-blur-md border-b border-gray-600">
        <div className="container mx-auto px-6 lg:px-16 py-4 flex items-center justify-between max-w-7xl">
          {/* Location */}
          <div className="flex items-center gap-2 text-white">
            <div className="w-2 h-2 bg-teal-500 rounded-full"></div>
            <span className="text-sm font-medium">Los Angeles, CA</span>
          </div>

          {/* Brand */}
          <div className="flex items-center gap-2">
            <div className="w-6 h-6 bg-teal-500 rounded-full flex items-center justify-center">
              <div className="w-3 h-3 bg-black rounded-full"></div>
            </div>
            <span className="text-white font-semibold text-lg">BADR EDDINE DIYAF</span>
          </div>

          {/* Menu Toggle */}
          <Button
            variant="outline"
            size="sm"
            className="rounded-full bg-transparent border-teal-500 text-teal-500 hover:bg-teal-500/20 hover:text-white"
            onClick={() => setIsMenuOpen(!isMenuOpen)}
          >
            {isMenuOpen ? <X className="h-4 w-4" /> : <Menu className="h-4 w-4" />}
            {isMenuOpen ? 'Close' : 'Menu'}
          </Button>
        </div>
      </nav>

      {/* Sidebar Menu Card */}
      <div
        className={`fixed top-20 right-6 w-96 bg-black rounded-2xl border border-gray-700 z-40 transform transition-all duration-300 ${
          isMenuOpen ? 'translate-x-0 opacity-100' : 'translate-x-96 opacity-0'
        }`}
      >
        <div className="p-6 flex space-x-6">
          {/* Menu Section */}
          <div className="flex-1">
            <h3 className="text-white text-sm font-medium mb-4 flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-teal-500 rounded-full"></div>
              Menu
            </h3>
            <ul className="space-y-1">
              {menuItems.map((item, index) => (
                <li key={index}>
                  <a
                    href={item.href}
                    className="group flex items-center gap-3 text-gray-200 hover:text-white hover:bg-gray-800/50 transition-all py-2.5 px-3 rounded-lg"
                    onClick={() => setIsMenuOpen(false)}
                  >
                    <item.icon className="w-4 h-4 text-gray-200 group-hover:text-teal-500" />
                    <span className="text-sm font-medium">{item.label}</span>
                  </a>
                </li>
              ))}
            </ul>
          </div>

          {/* Experience Items */}
          <div className="flex-1">
            <h3 className="text-white text-sm font-medium mb-4 flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-teal-500 rounded-full"></div>
              Experience
            </h3>
            <ul className="space-y-1">
              {experienceItems.map((item, index) => (
                <li key={index}>
                  <a
                    href={item.href}
                    className="group flex items-center gap-3 text-gray-200 hover:text-white hover:bg-gray-800/50 transition-all py-2.5 px-3 rounded-lg"
                    onClick={() => setIsMenuOpen(false)}
                  >
                    <item.icon className="w-4 h-4 text-gray-200 group-hover:text-teal-500" />
                    <span className="text-sm font-medium">{item.label}</span>
                  </a>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>

      {/* Overlay */}
      {isMenuOpen && (
        <div
          className="fixed inset-0 bg-black/30 z-30"
          onClick={() => setIsMenuOpen(false)}
        />
      )}
    </>
  );
}
